type GameProps = { room: PartyRoom; disabled: boolean; act: (a: PartyAction) => Promise<boolean>; sendDrawing?: DrawingSender };
const hands: Record<string, { symbol: string; title: string }> = { rock: { symbol: '✊', title: 'Rock' }, paper: { symbol: '✋', title: 'Paper' }, scissors: { symbol: '✌️', title: 'Scissors' } };
function HandDuel({ room, disabled, act }: GameProps) { const revealed = room.phase === 'reveal' || room.status === 'finished'; return <section className="party-panel party-duel"><span className="eyebrow">FIRST TO {room.game.targetWins ?? 3} WINS</span><h2>{revealed ? room.game.result?.text ?? 'The hands are in.' : room.self.choice ? 'Locked in. Nice poker face.' : 'Make your move.'}</h2><div className="party-duel-arena">{room.players.filter(p => !p.left).map(p => <div key={p.id}><strong><PartyPlayerName player={p}/>{p.id === room.self.id ? ' · you' : ''}</strong><span aria-label={revealed ? hands[room.game.choices?.[p.id]]?.title ?? 'No choice' : room.game.selectedIds?.includes(p.id) ? 'Choice locked' : 'Waiting'}>{revealed ? hands[room.game.choices?.[p.id]]?.symbol ?? '–' : room.game.selectedIds?.includes(p.id) ? '✓' : '?'}</span><small>{p.score} {p.score === 1 ? 'win' : 'wins'}</small></div>)}</div>{!revealed && <><div className="party-hand-options">{Object.entries(hands).map(([choice, hand]) => <button key={choice} disabled={disabled || Boolean(room.self.choice)} aria-pressed={room.self.choice === choice} onClick={() => void act({ type: 'choose', choice })}><span aria-hidden="true">{hand.symbol}</span><strong>{hand.title}</strong></button>)}</div><p className="party-note">{room.self.choice ? `You chose ${room.self.choice}. It stays private until both hands are in.` : 'Choose once. Both hands reveal together.'}</p></>}{revealed && room.status !== 'finished' && <RevealNext room={room} disabled={disabled} act={act}/>}</section>; }
