export function Starship({ room, disabled, now, act }: GameProps & { now: number }) {
  const [showRole, setShowRole] = useState(false); useEffect(() => setShowRole(false), [room.status === 'lobby', room.self.role]);
  const own = room.players.find(p => p.id === room.self.id), alive = own?.alive !== false, impostor = room.self.role === 'impostor', roaming = room.phase === 'roaming', rooms = room.game.rooms as { id: string; title: string; x: number; y: number; neighbors: string[] }[] ?? [], current = rooms.find(r => r.id === room.self.room), positions = room.game.positions as { id: string; room: string; alive: boolean }[] ?? [], sameRoom = positions.filter(p => p.id !== room.self.id && p.room === room.self.room && p.alive), bodies = room.game.bodies as { playerId: string; room: string }[] ?? [], tasks = room.self.tasks as { id: string; room: string; label: string; sequence: string[]; progress: number; complete: boolean }[] ?? [], sabotage = room.game.sabotage;
  return <><section className="party-panel party-ship-role"><div><span className="eyebrow">YOUR PRIVATE MISSION</span><h2>{showRole ? impostor ? 'You are an impostor.' : 'You are crew.' : 'Keep your role close.'}</h2><p>{showRole ? impostor ? 'Blend in, fake tasks and stop the crew. Tag someone in the same room or sabotage the reactor.' : alive ? 'Finish your task sequences and find the impostor. If you see a body, report it.' : 'You’re a ghost. You can still finish tasks to help the crew. Keep the culprit a secret.' : 'Your role and tasks are visible only to your seat.'}</p></div><button className="button secondary" aria-expanded={showRole} onClick={() => setShowRole(value => !value)}>{showRole ? 'Hide my role' : 'Reveal my role'}</button>{showRole && impostor && room.self.teammateIds?.length > 0 && <p className="party-private-note">Your team: {room.self.teammateIds.map((id: string) => partyPlayerLabel(room.players.find(p => p.id === id), 'Impostor')).join(', ')}</p>}</section><section className="party-panel party-ship"><div className="party-section-heading"><div><span className="eyebrow">THE SHIP</span><h2>{roaming ? `You’re in ${current?.title ?? 'the ship'}.` : room.phase === 'discussion' ? 'Let’s hear everyone out.' : room.phase === 'voting' ? 'Who is the suspect?' : 'Mission complete.'}</h2></div><span aria-hidden="true">✦</span></div><div className="party-task-progress"><label htmlFor="party-task-progress">Crew tasks <strong>{room.game.tasksCompleted ?? 0}/{room.game.tasksTotal ?? 0}</strong></label><progress id="party-task-progress" max={room.game.tasksTotal || 1} value={room.game.tasksCompleted ?? 0}/></div>{sabotage && room.status === 'playing' && <div className="party-sabotage" role="status"><strong>⚠ Reactor sabotage · {Math.max(0, Math.ceil(sabotage.deadlineAt - now))} seconds</strong><p>Reach the reactor and finish three repair steps before the countdown ends.</p>{roaming && room.self.room === sabotage.room && alive && <button className="button primary" disabled={disabled || now < (room.self.taskReadyAt ?? 0)} onClick={() => void act({ type: 'repair', step: sabotage.progress })}>Repair step {sabotage.progress + 1} of 3</button>}</div>}<div className="party-ship-map" aria-label="Ship rooms">{rooms.map((location, index) => { const here = location.id === room.self.room, reachable = current?.neighbors.includes(location.id), roomPlayers = positions.filter(p => p.room === location.id), roomBodies = bodies.filter(b => b.room === location.id); return <button key={location.id} className={`party-ship-room ship-room-${index}${here ? ' current' : ''}${reachable ? ' adjacent' : ''}`} disabled={disabled || !roaming || here || !reachable || now < (room.self.moveReadyAt ?? 0) || room.status !== 'playing'} onClick={() => void act({ type: 'move', room: location.id })}><span className="party-deck-symbol" aria-hidden="true">{['⌘', '⚡', '✚', '▣', '⚙'][index % 5]}</span><strong>{location.title}</strong><span className="party-room-avatars" aria-label={`${roomPlayers.length} players`}>{roomPlayers.map(p => { const player = room.players.find(player => player.id === p.id); return <span key={p.id} title={partyPlayerLabel(player)}>{player ? avatarFor(player.avatar)[1] : '●'}{!p.alive ? '◌' : ''}</span>; })}{roomBodies.map(b => <span key={`body-${b.playerId}`} title="Body to report">⚠</span>)}</span><small>{here ? 'You are here' : reachable && roaming ? 'Move here →' : location.neighbors.map(id => rooms.find(r => r.id === id)?.title).filter(Boolean).join(' · ')}</small></button>; })}</div>{roaming && room.status === 'playing' && <><p className="party-note">{now < (room.self.moveReadyAt ?? 0) ? 'Ready to move again in a moment…' : 'Select a connected room to move. Your game stays in sync with the group.'}</p><div className="party-ship-actions">{alive && bodies.filter(b => b.room === room.self.room).map(body => <button className="button primary" disabled={disabled} key={body.playerId} onClick={() => void act({ type: 'report', targetId: body.playerId })}>Report <PartyPlayerName player={room.players.find(p => p.id === body.playerId)} fallback="body"/></button>)}{alive && room.self.emergencyAvailable && <button className="button secondary" disabled={disabled} onClick={() => void act({ type: 'emergency' })}>Call a meeting</button>}{showRole && alive && impostor && <><button className="button danger" disabled={disabled || now < (room.self.sabotageReadyAt ?? 0) || Boolean(sabotage)} onClick={() => void act({ type: 'sabotage' })}>Sabotage reactor{now < (room.self.sabotageReadyAt ?? 0) ? ` · ${Math.ceil(room.self.sabotageReadyAt - now)}s` : ''}</button>{sameRoom.filter(p => !room.self.teammateIds?.includes(p.id)).map(p => <button className="button danger" disabled={disabled || now < (room.self.tagReadyAt ?? 0)} key={p.id} onClick={() => void act({ type: 'tag', targetId: p.id })}>Tag <PartyPlayerName player={room.players.find(player => player.id === p.id)}/>{now < (room.self.tagReadyAt ?? 0) ? ` · ${Math.ceil(room.self.tagReadyAt - now)}s` : ''}</button>)}</>}</div>{showRole && <section className="party-private-tasks"><span className="eyebrow">{impostor ? 'YOUR FAKE TASKS' : 'YOUR TASKS'}</span><p>{impostor ? 'Fake task steps blend in, but do not advance the crew’s progress.' : 'Go to the task’s room, then tap the symbols in order.'}</p>{tasks.map(task => <div className={task.complete ? 'complete' : ''} key={task.id}><div><strong>{task.complete ? '✓ ' : ''}{task.label}</strong><small>{rooms.find(r => r.id === task.room)?.title} · {task.complete ? 'complete' : `${task.progress}/${task.sequence.length} steps`}</small></div>{!task.complete && task.room === room.self.room && <div className="party-task-sequence">{now < (room.self.taskReadyAt ?? 0) && <small>Ready for the next step in a moment…</small>}{task.sequence.map((symbol, index) => <span key={index} className={index < task.progress ? 'done' : index === task.progress ? 'next' : ''}>{symbol}</span>)}<div>{['●', '▲', '■', '★'].map(symbol => <button key={symbol} aria-label={`Task symbol ${symbol}`} disabled={disabled || now < (room.self.taskReadyAt ?? 0)} onClick={() => void act({ type: 'task', taskId: task.id, step: symbol })}>{symbol}</button>)}</div></div>}</div>)}</section>}</>}{room.phase === 'discussion' && <div className="party-meeting"><p>{alive ? 'Share what you saw in room chat. Everyone can mark ready to open the vote sooner.' : 'You’re watching as a ghost. Keep what you know private until the game ends.'}</p>{alive && <button className="button primary" disabled={disabled || room.game.readyIds?.includes(room.self.id)} onClick={() => void act({ type: 'ready' })}>{room.game.readyIds?.includes(room.self.id) ? '✓ Ready to vote' : 'I’m ready to vote'}</button>}</div>}{room.phase === 'voting' && <div className="party-voting"><p>{alive ? room.self.vote ? 'Your ballot is locked. Votes stay private until the result.' : 'Choose a suspect or skip. Tied votes eject nobody.' : 'The living crew are voting. Your role stays secret.'}</p>{alive && <div>{room.players.filter(p => p.alive && !p.left).map(p => <button className="button secondary" disabled={disabled || Boolean(room.self.vote)} aria-pressed={room.self.vote === p.id} key={p.id} onClick={() => void act({ type: 'vote', targetId: p.id })}>{avatarFor(p.avatar)[1]} <PartyPlayerName player={p}/></button>)}<button className="button secondary" disabled={disabled || Boolean(room.self.vote)} aria-pressed={room.self.vote === 'skip'} onClick={() => void act({ type: 'vote', targetId: 'skip' })}>Skip this vote</button></div>}<small>{room.game.votedIds?.length ?? 0} ballots submitted.</small></div>}</section></>;
}
